{
  "title": "TB Transmission Learning Game",
  "perWatchSecond": 0.2,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "Eliminate TB by lowering contact",
      "goal": "Show that reducing the contact rate can bring TB below elimination threshold.",
      "control": {
        "parameter": "beta",
        "label": "Contact rate",
        "lowEnd": "0.02",
        "highEnd": "0.10"
      },
      "watch": "Infectious population (i)",
      "whatIf": {
        "prompt": "What if beta is set to 0.02?",
        "parameter": "beta",
        "value": 0.02
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 30,
        "relation": "lower",
        "by": 30
      },
      "effect": "With beta reduced to 0.02, the peak number of infectious people is lower by at least 30 compared to the baseline.",
      "prediction": {
        "prompt": "Will the peak infectious count be lower?",
        "claimed": "Peak infectious will be lower",
        "other": "Peak infectious will be higher"
      },
      "passage": {
        "title": "Headline result",
        "quote": "The results suggest that optimal conditions could lead to the elimination of TB."
      },
      "carryForward": "Next we examine the estimated reproduction number."
    },
    {
      "kind": "background",
      "finding": 1,
      "title": "Higher recruitment raises infections",
      "goal": "Demonstrate that increasing population recruitment raises the average infectious count.",
      "control": {
        "parameter": "lambda",
        "label": "Recruitment rate",
        "lowEnd": "10",
        "highEnd": "30"
      },
      "watch": "Infectious population (i)",
      "whatIf": {
        "prompt": "What if recruitment is increased to 22.5?",
        "parameter": "lambda",
        "value": 22.5
      },
      "difference": {
        "compartment": "i",
        "summary": "mean",
        "at": null,
        "time": 30,
        "relation": "higher",
        "by": 20
      },
      "effect": "Increasing recruitment to 22.5 raises the average infectious count by at least 20.",
      "prediction": {
        "prompt": "Will more recruitment increase infections?",
        "claimed": "Infections will increase",
        "other": "Infections will decrease"
      },
      "passage": {
        "title": "Threshold",
        "quote": "We obtained $R_0 = 2.67$ for the estimated model parameters, which are greater than one, indicating that the tuberculosis is continuously multiplying."
      },
      "carryForward": "Now we look at treatment."
    },
    {
      "kind": "method",
      "finding": 2,
      "title": "Faster treatment cuts peak",
      "goal": "Show that doubling the treatment rate reduces the peak infectious population.",
      "control": {
        "parameter": "delta",
        "label": "Treatment rate",
        "lowEnd": "0.3",
        "highEnd": "1.0"
      },
      "watch": "Infectious population (i)",
      "whatIf": {
        "prompt": "What if the treatment rate is doubled to 1.34?",
        "parameter": "delta",
        "value": 1.34
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 30,
        "relation": "lower",
        "by": 40
      },
      "effect": "Doubling the treatment rate to 1.34 lowers the peak infectious count by at least 40.",
      "prediction": {
        "prompt": "Will faster treatment reduce peak infections?",
        "claimed": "Peak will be lower",
        "other": "Peak will be higher"
      },
      "passage": {
        "title": "Treatment effect",
        "quote": "The result revealed that the infectious population decreases as the treatment rate of infected individuals increases; in the long run, this may lead to the eradication of the disease from the community."
      },
      "carryForward": "Finally we could explore vaccination, but the core lessons are covered."
    }
  ],
  "limits": [
    "All levels run for 30 years.",
    "The game updates four times faster than real time."
  ]
}
